using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        ILogger<IMcpServer> logger,
        [Description("The API endpoint path (e.g. \"users/1\").")] string endpoint,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Calling external API: {Endpoint}", endpoint);

        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(endpoint, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return json.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Maximum number of sentences in the summary (default: 3).")] int? maxSentences = 3)
    {
        return new GetPromptResult
        {
            Description = "Summarization prompt",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new ContentBlock
                    {
                        Text = $"Summarize the following text in at most {maxSentences ?? 3} sentences:\n\n{text}",
                        Type = "text"
                    }
                }
            ]
        };
    }
}

